import{_ as l,C as a,o as n,c as d,a2 as e,b as c,w as s,a as p,E as i,a3 as h}from"./chunks/framework.CHjbm2Wd.js";const w=JSON.parse('{"title":"Fault protection & mode logic","description":"FDIR, safe modes, watchdogs, voting, recovery, and one-shot landing constraints.","frontmatter":{"title":"Fault protection & mode logic","description":"FDIR, safe modes, watchdogs, voting, recovery, and one-shot landing constraints."},"headers":[],"relativePath":"flight/fault-protection.md","filePath":"flight/fault-protection.md","lastUpdated":1792993690000}'),u={name:"flight/fault-protection.md"};function m(g,t,b,f,v,A){const o=a("Mermaid"),r=a("Quiz");return n(),d("div",null,[t[1]||(t[1]=e('<h1 id="fault-protection-mode-logic" tabindex="-1">Fault protection &amp; mode logic <a class="header-anchor" href="#fault-protection-mode-logic" aria-label="Permalink to &quot;Fault protection &amp; mode logic&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Why this matters</p><p>A lunar lander is a one-shot system. There is no hangar, no rescue, and often no second attempt. Fault protection is not a feature you add at the end; it is the architecture that decides what the vehicle does when a sensor lies, an actuator sticks, or a deadline is missed.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Define fault detection, isolation, and recovery (FDIR).</li><li>Design a mode state machine with guards and priorities.</li><li>Choose detection methods and set thresholds that do not nuisance-trip.</li><li>Design safe mode, abort, and divert behavior.</li><li>Analyze detection latency and recovery time.</li><li>Test fault paths with injection, not just nominal cases.</li></ul><h2 id="fdir-in-one-page" tabindex="-1">FDIR in one page <a class="header-anchor" href="#fdir-in-one-page" aria-label="Permalink to &quot;FDIR in one page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Question</th><th>Example</th></tr></thead><tbody><tr><td><strong>Detection</strong></td><td>Is something wrong?</td><td>IMU sample is 300 ms old</td></tr><tr><td><strong>Isolation</strong></td><td>What is wrong?</td><td>IMU-A is stale; IMU-B is valid</td></tr><tr><td><strong>Recovery</strong></td><td>What do we do?</td><td>Switch to IMU-B, log event, continue</td></tr><tr><td><strong>Reconfiguration</strong></td><td>What changes?</td><td>Nav uses IMU-B; control uses the backup rate</td></tr><tr><td><strong>Reporting</strong></td><td>What does the ground see?</td><td>Event + telemetry with timestamp</td></tr></tbody></table><p>Detection without isolation can disable the wrong unit. Isolation without recovery leaves the vehicle in a degraded state. Recovery without reporting leaves the ground confused.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><p>A descent mode set might be:</p>',9)),(n(),c(h,null,{default:s(()=>[i(o,{id:"mermaid-127",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20SAFE%0A%20%20%20%20SAFE%20--%3E%20STANDBY%3A%20ground%20enable%0A%20%20%20%20STANDBY%20--%3E%20ATTITUDE_HOLD%3A%20nav%20valid%0A%20%20%20%20ATTITUDE_HOLD%20--%3E%20DESCENT_BRAKING%3A%20PDI%20command%0A%20%20%20%20DESCENT_BRAKING%20--%3E%20DESCENT_APPROACH%3A%20altitude%2Fvelocity%20gate%0A%20%20%20%20DESCENT_APPROACH%20--%3E%20TERMINAL_DESCENT%3A%20gate%0A%20%20%20%20TERMINAL_DESCENT%20--%3E%20TOUCHDOWN%3A%20contact%0A%20%20%20%20TOUCHDOWN%20--%3E%20SAFED%3A%20engine%20cutoff%0A%20%20%20%20DESCENT_BRAKING%20--%3E%20SAFE%3A%20fault%0A%20%20%20%20DESCENT_APPROACH%20--%3E%20SAFE%3A%20fault%0A%20%20%20%20TERMINAL_DESCENT%20--%3E%20DIVERT%3A%20hazard%0A%20%20%20%20DIVERT%20--%3E%20TERMINAL_DESCENT%3A%20new%20target%0A%20%20%20%20SAFED%20--%3E%20%5B*%5D%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[p(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e(`<p>Every transition needs:</p><ul><li>a <strong>guard</strong> (conditions, sensor validity, authority),</li><li>an <strong>action</strong> (command, configuration, telemetry),</li><li>a <strong>priority</strong> (fault transitions override nominal),</li><li>a <strong>test</strong>.</li></ul><p>Avoid two-authority designs where guidance and FDIR both command the same actuator without arbitration. Define who owns the actuator in each mode.</p><h2 id="detection-methods" tabindex="-1">Detection methods <a class="header-anchor" href="#detection-methods" aria-label="Permalink to &quot;Detection methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Use</th><th>Risk</th></tr></thead><tbody><tr><td><strong>Range/threshold</strong></td><td>Altitude, rate, temperature, voltage</td><td>Nuisance trips at the boundary</td></tr><tr><td><strong>Rate of change</strong></td><td>Sudden jumps, divergence</td><td>Noise sensitivity</td></tr><tr><td><strong>Stale data</strong></td><td>Timestamp age</td><td>Clock mismatch</td></tr><tr><td><strong>Watchdog</strong></td><td>Software hang</td><td>Reset loops, lost context</td></tr><tr><td><strong>CRC/checksum</strong></td><td>Corrupt memory or packet</td><td>Undetected multi-bit errors</td></tr><tr><td><strong>Voting</strong></td><td>Redundant sensors/computers</td><td>Common-mode failure</td></tr><tr><td><strong>Model residual</strong></td><td>Filter innovation, dynamics mismatch</td><td>Model error</td></tr><tr><td><strong>Sequence gap</strong></td><td>Dropped packets</td><td>Reordering vs loss</td></tr><tr><td><strong>Limit checking</strong></td><td>Command/telemetry bounds</td><td>Wrong limits</td></tr></tbody></table><p>A good detector has a <strong>false-positive rate</strong>, a <strong>detection latency</strong>, and a <strong>coverage</strong> claim. Test all three.</p><h2 id="thresholds-and-hysteresis" tabindex="-1">Thresholds and hysteresis <a class="header-anchor" href="#thresholds-and-hysteresis" aria-label="Permalink to &quot;Thresholds and hysteresis&quot;">​</a></h2><p>A threshold with no hysteresis will chatter. Use:</p><ul><li>a trip threshold and a clear threshold,</li><li>a persistence count or time,</li><li>a rate limit,</li><li>a validity window,</li><li>a fault confirmation before reconfiguration.</li></ul><p>Example: declare an IMU stale after 3 consecutive samples older than 100 ms, not after one late sample. Clear only after 10 consecutive valid samples. Log both the trip and the clear.</p><h2 id="safe-mode" tabindex="-1">Safe mode <a class="header-anchor" href="#safe-mode" aria-label="Permalink to &quot;Safe mode&quot;">​</a></h2><p>Safe mode should be a known, tested state:</p><ul><li>safe attitude (often sun-pointing or a thermally safe attitude),</li><li>engine off,</li><li>RCS safe,</li><li>minimum power,</li><li>telemetry on,</li><li>commanding enabled,</li><li>watchdog active,</li><li>fault context preserved.</li></ul><p>Safe mode is not “do nothing.” It is a controlled state with a defined power, thermal, and communications posture.</p><h2 id="abort-and-divert" tabindex="-1">Abort and divert <a class="header-anchor" href="#abort-and-divert" aria-label="Permalink to &quot;Abort and divert&quot;">​</a></h2><p>For a one-shot landing:</p><ul><li><strong>Abort to orbit</strong> requires delta-v, time, and a viable orbit.</li><li><strong>Divert</strong> requires a secondary site and enough fuel/time.</li><li><strong>Hover</strong> buys time but burns fuel.</li><li><strong>Continue degraded</strong> is only acceptable if the evidence supports it.</li></ul><p>Each option needs a trigger, a time budget, a fuel budget, and a test. Do not assume “abort” is always available.</p><h2 id="one-shot-landing-constraints" tabindex="-1">One-shot landing constraints <a class="header-anchor" href="#one-shot-landing-constraints" aria-label="Permalink to &quot;One-shot landing constraints&quot;">​</a></h2><p>The terminal descent is unforgiving:</p><ul><li>detection latency must be short enough to act,</li><li>recovery may be impossible below a certain altitude,</li><li>a stuck thruster may be unrecoverable,</li><li>a wrong attitude may be worse than a wrong altitude,</li><li>plume/dust can blind sensors,</li><li>contact detection must be robust.</li></ul><p>This shifts emphasis to:</p><ul><li><strong>pre-flight verification</strong> and Monte Carlo,</li><li><strong>fault tolerance by design</strong> (redundancy, margins),</li><li><strong>conservative guidance</strong> with reserves,</li><li><strong>tested fault responses</strong> at the terminal phase,</li><li><strong>clear authority</strong> between crew/ground and autonomy.</li></ul><h2 id="fault-tree-example" tabindex="-1">Fault tree example <a class="header-anchor" href="#fault-tree-example" aria-label="Permalink to &quot;Fault tree example&quot;">​</a></h2><p>Top event: “uncontrolled descent at touchdown.”</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Uncontrolled descent</span></span>
<span class="line"><span>├── Navigation fault</span></span>
<span class="line"><span>│   ├── IMU bias/drift undetected</span></span>
<span class="line"><span>│   ├── Altimeter stuck</span></span>
<span class="line"><span>│   └── Frame/time error</span></span>
<span class="line"><span>├── Guidance fault</span></span>
<span class="line"><span>│   ├── Infeasible command</span></span>
<span class="line"><span>│   ├── Mode transition error</span></span>
<span class="line"><span>│   └── Target error</span></span>
<span class="line"><span>├── Control fault</span></span>
<span class="line"><span>│   ├── Actuator saturation</span></span>
<span class="line"><span>│   ├── Stuck RCS</span></span>
<span class="line"><span>│   └── Gain/table error</span></span>
<span class="line"><span>├── FDIR fault</span></span>
<span class="line"><span>│   ├── Detector missed</span></span>
<span class="line"><span>│   ├── Wrong isolation</span></span>
<span class="line"><span>│   └── Recovery too late</span></span>
<span class="line"><span>└── Environment/model</span></span>
<span class="line"><span>    ├── Terrain higher than map</span></span>
<span class="line"><span>    ├── Plume/dust blindness</span></span>
<span class="line"><span>    └── Gravity/model error</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>For each leaf, define detection, mitigation, and evidence. A fault tree without evidence is a brainstorm.</p><h2 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h2><p>For each fault:</p><ul><li><strong>detection latency</strong> — how long until the fault is declared,</li><li><strong>isolation latency</strong> — how long until the failed unit is identified,</li><li><strong>recovery latency</strong> — how long until the safe/alternate state is active,</li><li><strong>total time to safe</strong> — compare to the available time.</li></ul><p>A fault that is detected in 2 s but leaves only 1 s to recover is not protected.</p><h2 id="testing-faults" tabindex="-1">Testing faults <a class="header-anchor" href="#testing-faults" aria-label="Permalink to &quot;Testing faults&quot;">​</a></h2><ul><li>inject one fault at a time,</li><li>inject combinations that could defeat redundancy,</li><li>test at the worst time (terminal descent),</li><li>test the detector’s false-positive rate with noise,</li><li>test recovery transients,</li><li>test the reset/watchdog path,</li><li>test the ground command path,</li><li>log the decision, not just the outcome.</li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Draw a mode state machine for your descent sim with at least five modes and three fault transitions.</li><li>Implement a stale-nav detector with persistence and hysteresis. Test it with noise and a real dropout.</li><li>Add a redundant IMU and a voting/isolation rule. Inject a bias fault.</li><li>Write a fault tree for “landing miss &gt; 100 m.” Add one evidence item per leaf.</li><li>Measure detection-to-safe time for a stuck altimeter at 100 m altitude.</li></ol>`,35)),i(r,{question:"A fault is detected in 2 seconds and recovery takes 3 seconds, but the available time before touchdown is 4 seconds. What is the correct conclusion?",options:"The fault is protected because it was detected|The total time to safe exceeds the available time, so the response is not adequate|The detector needs a lower threshold|Recovery is optional",answer:"1",explanation:"Detection time plus isolation plus recovery must fit inside the available time, with margin. Detecting a fault you cannot recover from in time is not protection."}),t[3]||(t[3]=e('<h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://swehb.nasa.gov/" target="_blank" rel="noreferrer">NASA Fault Detection, Isolation, and Recovery</a> — software engineering handbook material.</li><li><a href="https://www.nasa.gov/connect/ebooks/nasa-systems-engineering-handbook/" target="_blank" rel="noreferrer">NASA Systems Engineering Handbook</a> — fault trees and risk.</li><li><a href="https://nodis3.gsfc.nasa.gov/displayDir.cfm?t=NPR&amp;c=7150&amp;s=2" target="_blank" rel="noreferrer">NPR 7150.2</a> — software assurance and safety.</li><li><a href="https://github.com/nasa/HS" target="_blank" rel="noreferrer">cFS Health &amp; Safety</a> — a concrete watchdog/monitoring implementation.</li></ul><p>Next: <a href="./sensors-actuators.html">sensors &amp; actuators</a>.</p>',3))])}const T=l(u,[["render",m]]);export{w as __pageData,T as default};
